command:
cat > /tmp/named.conf <<'ANTRIEB_NAMED_EOF'
options {
    listen-on port 53 { any; };
    listen-on-v6 port 53 { none; };
    directory "/var/named";
    key-directory "/var/named/dynamic";
    pid-file "/run/named/named.pid";
    session-keyfile "/run/named/session.key";
    recursion no;
    allow-query { any; };
    allow-transfer { none; };
    dnssec-validation auto;
    minimal-responses yes;
};

include "/etc/named.infra-update.key";

zone "infra.test" IN {
    type master;
    file "dynamic/infra.test";
    update-policy { grant infra-update zonesub ANY; };
    allow-transfer { 10.100.202.11; 10.100.202.12; };
    also-notify { 10.100.202.11; 10.100.202.12; };
    notify yes;
    dnssec-policy default;
    inline-signing yes;
};
ANTRIEB_NAMED_EOF
named-checkconf /tmp/named.conf
install -o root -g named -m 0640 /tmp/named.conf /etc/named.conf
rm -f /tmp/named.conf
printf 'Primary named.conf validated and installed\n'

